// ready unless its handler implements Ready() (bool, string) and reports otherwise.
func (d *SessionProjectDispatcher) DescribeService() (contract string, ready bool, why string) {
	if h, ok := d.Handler.(interface{ Ready() (bool, string) }); ok {
		if ready, why = h.Ready(); ready {
			why = ""
		}
		return "openabstractions.opencode/session-project@1", ready, why
	}
	return "openabstractions.opencode/session-project@1", true, ""
}

